<?php require __DIR__.'/../_init.php'; adminHeader('Customers'); ?><p>Customer accounts and purchase history. Roles are managed only through the local database.</p><table><tr><th>Name</th><th>Email</th><th>Joined</th><th>Orders</th><th>Total ordered</th></tr><?php foreach($pdo->query("SELECT u.id,u.name,u.email,u.created_at,COUNT(o.id) AS orders,COALESCE(SUM(CASE WHEN o.status<>'cancelled' THEN o.total ELSE 0 END),0) AS total FROM users u LEFT JOIN orders o ON o.user_id=u.id WHERE u.role='user' GROUP BY u.id,u.name,u.email,u.created_at ORDER BY u.id DESC") as $r): ?><tr><td><a href="view.php?id=<?= (int)$r['id'] ?>"><?= e($r['name']) ?></a></td><td><?= e($r['email']) ?></td><td><?= e($r['created_at']) ?></td><td><?= (int)$r['orders'] ?></td><td>৳<?= e($r['total']) ?></td></tr><?php endforeach ?></table><?php adminFooter(); ?>